"""Publish verified CPU copy/wait and real-disc boot-loop discovery."""
import hashlib,json,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1];RUNTIME=Path.home()/'.lmstudio/local-ai-lab'
save=lambda p,v:p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')

def main():
    proof=json.loads((ROOT/'verification/firmware-post-GPU-CPU-checks.json').read_text());assert proof['source_instruction_coverage']==[15,15] and proof['checkpoints']==20 and proof['emulator_shutdown_completed']
    attached=json.loads((ROOT/'verification/BIWN-relocated-firmware-observation/20261015T033530.239174Z/report.json').read_text());assert attached['disc_attached'] and attached['emulator_shutdown_completed']
    events=attached['further_explicit_video_events'];assert len(events)==6 and events[-1]['CPU_after']['pc']==0x5021c
