    prior=json.loads((ROOT/'verification/firmware-initial-GPU-review.json').read_text());compact=dict(prior['evidence'])
    compact.update(status=proof['status'],recorded_at=proof['recorded_at'],audit=str(out),full_report=str(ROOT/'verification/firmware-post-GPU-CPU-checks.json'),post_GPU_CPU_C_verified=True,post_GPU_CPU_instruction_coverage=[15,15],post_GPU_CPU_instructions=433,post_GPU_CPU_checkpoints=20,post_GPU_CPU_original_instructions_on_C_path=0,main_firmware_CPU_still_original=True,main_firmware_CPU_scope='Main CPU outside the checked video IRQ handler and new 15-instruction post-GPU copy/wait still runs original instructions.',private_Blitter_state_compared=False,Blitter_scope='TOM register/RAM snapshots include Blitter MMIO registers. Pinned core does not export BlitterStateSave; private execution state was not compared in either live or standalone renderer proof.',disc_attached=True,disc_attached_scope='Internal original CDI attached in separate diagnostic run; no source disc-header/loading or firmware-to-game dispatch verified.',further_video_handlers_use_original_CPU=True)
    compact['processor_responsibilities']['C_post_GPU_CPU']='Fifteen reached CPU instructions copy 228 bytes from source RAM to1000, naturally jump1000 and wait for counter delta5. All433steps/20checkpoints match independent original CPU. Computed registers/banks/PC exported without core pulse reset. Further handlers/main boot remain original.'
    compact['next_CPU_after_GPU'].update(status='first_15_instructions_C_verified',source_C_verified=True,checkpoints=20)
    compact['real_disc_boot_observation']=dict(directory=attached['directory'],internal_CDI_attached=True,extracted_boot_payload_hostcopy=False,explicit_further_video_events=6,original_CPU_followup=True,fifth_event_installs_source_vector='0x1026',sixth_event_clears_source_video_counter_and_restores_vector='0x194c90',source_bootstrap_reentry='0x802000',final_CPU_wait='0x5021c',actual_disc_header_loading_verified=False,physical_event_period_verified=False)
    compact['plain_language_summary']='The CPU copy/jump/video wait is now reconstructed C: 15 source instructions, 433 executed steps and 20 checkpoints match the original CPU. It copies 228 bytes to1000 and enters the five-counter wait. Initial GPU wait, resumed GPU renderer, DSP and first video IRQ C components remain verified in their earlier scopes. Further video interrupts still run original CPU instructions. Six explicit follow-up events, including a run with the real internal CDI attached, lead back into BIOS entry802000 and the DSP wait5021C; no game boot stub was injected. Disc presence alone did not resolve the boot loop. Remaining firmware/CD bus behavior, event timing and natural game loading must be resolved; the full rebuilt game cannot boot yet.'
    compact['next_GPU_CPU_dependency']=dict(status='Post-GPU CPU copy/wait C verified; attached-disc BIOS loop discovered',next_action='Resolve the source BIOS/cartridge/controller boot-loop behavior and processor-specific ROM reads, then reach actual source disc header/loading and natural game dispatch. Extend C to the delta-five fallthrough/new video handler and remaining main CPU. Derive physical global event timing and extend whole-game paths.')
    external=dict(url='https://github.com/mamedev/mame/blob/master/src/mame/atari/jaguar.cpp',raw_url='https://raw.githubusercontent.com/mamedev/mame/master/src/mame/atari/jaguar.cpp',function='jaguarcd_state::cd_bios_r',observed_code='MAME has a documented reset workaround returning5 to DSP reads of800408; it labels this a hack. This corroborates a known emulator boot-loop issue but does not establish correct hardware behavior or authorize treating the workaround as source equivalence.',use='Diagnostic next-step lead only; not implemented in our current source proof.')
    save(out/'external-diagnostic-reference.json',external);save(out/'compact-evidence.json',compact)
    for base in [ROOT,RUNTIME]:
        folder=Path(json.loads((base/'projects/black-ice-white-noise/analysis/current-session.json').read_text())['directory']);p=folder/'emulator-runtime/summary.json';data=json.loads(p.read_text());data['firmware_bootstrap_DSP_progress']=compact;save(p,data)
    files=[ROOT/'verification/firmware-post-GPU-CPU-checks.json',ROOT/'scripts/generate_biwn_firmware_post_GPU_cpu.py',ROOT/'scripts/check_biwn_firmware_post_GPU_cpu.py',ROOT/'scripts/observe_biwn_relocated_firmware.py',ROOT/'scripts/record_firmware_post_GPU_checkpoint.py']
    files.extend(ROOT/'projects/black-ice-white-noise/restoration'/name for name in proof['source_sha256'])
    files.extend(Path(proof['directory'])/name for name in ['native-checkpoints.json','comparisons.json','report.json','post-GPU-CPU-compiler.txt'])
    for folder in [Path(proof['native_directory']),Path(proof['C_directory']),Path(attached['directory'])]:files.extend(folder/name for name in ['protocol.json','report.json','status.json','CPU-after-GPU.json','CPU-after-GPU.txt','RAM-after-GPU-CPU.bin','further-video-05.json'])
    files.extend(Path(attached['directory'])/name for name in ['further-video-06.json','RAM-after-further-video-06.bin'])
